const updateExternalIncidentIssue = `-- name: UpdateExternalIncidentIssue :one
UPDATE issue AS current_issue
SET title = $1,
    description = $2,
    position = CASE WHEN status IS DISTINCT FROM $3 THEN (
        SELECT COALESCE(MIN(target.position), 0) - 1
        FROM issue AS target
        WHERE target.workspace_id = current_issue.workspace_id AND target.status = $3
    ) ELSE position END,
    status = $3,
    priority = $4,
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('external_incident', $5::jsonb),
    revision = revision + 1,
    last_activity_at = GREATEST(COALESCE(last_activity_at, updated_at), now()),
    updated_at = now()
WHERE current_issue.id = $6 AND current_issue.workspace_id = $7
  AND current_issue.origin_type = 'external_incident' AND current_issue.origin_id = $8
RETURNING id, workspace_id, title, description, status, priority, assignee_type, assignee_id, creator_type, creator_id, parent_issue_id, acceptance_criteria, context_refs, position, due_date, created_at, updated_at, number, project_id, origin_type, origin_id, first_executed_at, start_date, metadata, stage, properties, revision, last_activity_at
`

type UpdateExternalIncidentIssueParams struct {
	Title            string      `json:"title"`
	Description      pgtype.Text `json:"description"`
	Status           string      `json:"status"`
	Priority         string      `json:"priority"`
	IncidentMetadata []byte      `json:"incident_metadata"`
	ID               pgtype.UUID `json:"id"`
	WorkspaceID      pgtype.UUID `json:"workspace_id"`
	OriginID         pgtype.UUID `json:"origin_id"`
}

